def transform(grid):
    """Transform grid: fill around T-junction with 9-7-9 pattern"""
    h, w = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    # Find horizontal bar (full row of same non-background color)
    for r in range(h):
        if len(set(grid[r])) == 1 and grid[r][0] != 0 and grid[r][0] != 6:
            bar_row = r
            bar_color = grid[r][0]
            break

    # Find vertical bars
    vertical_bars = []
    for c in range(w):
        if c == 0 or grid[r][c] == bar_color and all(grid[row][c] == bar_color for row in range(h)):
            vertical_bars.append(c)

    if vertical_bars:
        # Determine fill strategy based on number of vertical bars
        if len(vertical_bars) == 2:
            # TWO vertical bars: fill BETWEEN with 9-7-9
            c1, c2 = vertical_bars
            for c in range(c1 + 1, c2):
                if c == c1 + 1:
                    fill_color = 9
                elif c == c2 - 1:
                    fill_color = 9
                else:
                    fill_color = 7
                for row in range(h):
                    if grid[row][c] != bar_color:
                        result[row][c] = fill_color
        elif len(vertical_bars) == 1:
            # ONE vertical bar: fill adjacent columns with 9-7-9 pattern
            c = vertical_bars[0]
            for row in range(h):
